import { useState } from 'react'
import { Link } from 'react-router-dom'
import { useLiveQuery } from 'dexie-react-hooks'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { dating, datingLabelKey } from './pregnancyMath'
import type { FamilyRecord } from '@/types/domain'
import { useI18n, useT, type MessageKey } from '@/i18n'
import { fmtDate, whenLabel } from '@/i18n/format'

/**
 * Keluarga (FAM-01..06).
 *
 * Every module here is opt-in and stays off until switched on — TemuDua does not
 * assume a couple wants children, and turning a module off must not read as a
 * statement about them. Body data belongs to the person whose body it is;
 * child records are shared between the people raising the child.
 */

type ModuleKey = 'pregnancy' | 'child' | 'coparenting'
type SheetKind = FamilyRecord['kind'] | null

export default function Family() {
  const { t, locale } = useI18n()
  const { profile, profiles } = useSession()
  const me = profile?.id
  const [sheet, setSheet] = useState<SheetKind>(null)
  const rows = useOwned<FamilyRecord>('family', me)
  const active = useLiveQuery(
    async () => ((await db.settings.get('family.modules'))?.value as ModuleKey[]) ?? [],
    [],
  )

  if (!profile || !me) return null
  const on = active ?? []

  const of = <K extends FamilyRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is Extract<FamilyRecord, { kind: K }> => r.kind === kind)

  const pregnancies = of('pregnancy').filter((p) => p.status === 'jalan')
  const appointments = of('appointment').sort((a, b) => a.date.localeCompare(b.date))
  const birthPlan = of('birth_plan')
  const supports = of('support_request')
  const children = of('child')
  const growth = of('growth')
  const immunizations = of('immunization')
  const shifts = of('shift').sort((a, b) => a.date.localeCompare(b.date))

  async function toggle(key: ModuleKey) {
    const next = on.includes(key) ? on.filter((k) => k !== key) : [...on, key]
    await db.settings.put({ key: 'family.modules', value: next })
  }

  return (
    <div className="stack">
      <h1>{t('nav.family')}</h1>
      <p className="card__hint">{t('fam.subtitle')}
      </p>

      <Card title={t('fam.modules')} icon="settings">
        <div className="choices">
          {(
            [
              'pregnancy',
              'child',
              'coparenting',
            ] as const
          ).map((key) => (
            <button
              key={key}
              type="button"
              aria-pressed={on.includes(key)}
              className="choice"
              onClick={() => toggle(key)}
            >
              <Icon name={key === 'pregnancy' ? 'pregnancy' : key === 'child' ? 'baby' : 'family'} size={24} animate />
              <span className="stack stack--tight grow">
                <span className="choice__title">{t(`fam.mod.${key}` as const)}</span>
                <span className="choice__desc">{t(`fam.mod.${key}.desc` as const)}</span>
              </span>
              {on.includes(key) && <Icon name="check" size={20} />}
            </button>
          ))}
        </div>
      </Card>

      <Card title={t('cyc.title')} icon="cycle" hint={t('fam.cycleCardHint')}>
        <Link to="/siklus" className="btn btn--soft btn--block">
          <Icon name="cycle" size={18} />{t('fam.openCycle')}
        </Link>
      </Card>

      {on.includes('pregnancy') && (
        <>
          <Card
            title={t('fam.mod.pregnancy')}
            icon="pregnancy"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('pregnancy')}>
                <Icon name="plus" size={16} /> {t('cyc.record')}
              </button>
            }
          >
            {pregnancies.length === 0 ? (
              <EmptyState
                icon="pregnancy"
                title={t('fam.noPregnancy')}
                hint={t('fam.noPregnancyHint')}
              />
            ) : (
              pregnancies.map((p) => {
                const d = dating(p.lmpDate)
                return (
                  <div key={p.id} className="stack stack--tight">
                    <strong>
                      {t(datingLabelKey(d), {
                        week: d.weeks,
                        day: d.days,
                        trimester: d.trimester ?? '',
                      })}
                    </strong>
                    {!d.outOfRange && (
                      <p className="card__hint">
                        {t('fam.dueDate', {
                          date: fmtDate(d.estimatedDueDate, 'd MMMM yyyy', locale),
                          days: d.daysRemaining,
                        })}
                      </p>
                    )}
                    <div className="row">
                      <VisibilityBadge visibility={p.visibility} />
                      <button className="btn btn--ghost btn--sm" onClick={() => patch('family', p.id, { status: 'selesai' })}>{t('fam.markFinished')}
                      </button>
                    </div>
                  </div>
                )
              })
            )}
            <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>{t('fam.pregnancyDisclaimer')}
            </p>
          </Card>

          <Card
            title={t('fam.appointments')}
            icon="health"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('appointment')}>
                <Icon name="plus" size={16} /> {t('fam.appointment')}
              </button>
            }
            hint={t('fam.appointmentsHint')}
          >
            {appointments.length === 0 ? (
              <EmptyState icon="health" title={t('fam.noAppointments')} />
            ) : (
              <ul className="list">
                {appointments.map((a) => (
                  <li key={a.id} className="list__item">
                    <Icon name="health" size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{a.title}</strong>
                      <span className="card__hint">
                        {whenLabel(a.date, t, locale)}
                        {a.time ? ` · ${a.time}` : ''}
                        {a.place ? ` · ${a.place}` : ''}
                      </span>
                      {a.questions.length > 0 && (
                        <span className="card__hint">
                          {t('fam.wantToAsk', { questions: a.questions.join('; ') })}
                        </span>
                      )}
                    </span>
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('family', a.id, me)}>
                      <Icon name="close" size={16} label={t('common.delete')} />
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Card>

          <Card
            title={t('fam.birthPlan')}
            icon="consent"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('birth_plan')}>
                <Icon name="plus" size={16} /> {t('common.add')}
              </button>
            }
            hint={t('fam.birthPlanHint')}
          >
            {birthPlan.length === 0 ? (
              <EmptyState icon="consent" title={t('today.noUnsaid')} />
            ) : (
              <ul className="list">
                {birthPlan.map((b) => (
                  <li key={b.id} className="list__item">
                    <span className="grow">{b.preference}</span>
                    <VisibilityBadge visibility={b.visibility} />
                  </li>
                ))}
              </ul>
            )}
          </Card>

          <Card
            title={t('fam.support')}
            icon="shared"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('support_request')}>
                <Icon name="plus" size={16} /> {t('fam.supportAsk')}
              </button>
            }
            hint={t('fam.supportHint')}
          >
            {supports.length === 0 ? (
              <EmptyState icon="shared" title={t('fam.noSupport')} hint={t('fam.noSupportHint')} />
            ) : (
              <ul className="list">
                {supports.map((s) => (
                  <li key={s.id} className="list__item">
                    <span className="grow">{s.action}</span>
                    <span className="chip">{t(`fam.status.${s.status}` as const)}</span>
                    {s.status === 'diminta' && (
                      <button className="btn btn--soft btn--sm" onClick={() => patch('family', s.id, { status: 'diambil' })}>{t('fam.takeIt')}
                      </button>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </Card>
        </>
      )}

      {on.includes('child') && (
        <>
          <Card
            title={t('fam.children')}
            icon="baby"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('child')}>
                <Icon name="plus" size={16} /> {t('common.add')}
              </button>
            }
          >
            {children.length === 0 ? (
              <EmptyState icon="baby" title={t('fam.noChildren')} />
            ) : (
              <ul className="list">
                {children.map((c) => (
                  <li key={c.id} className="list__item">
                    <Icon name="baby" size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{c.name}</strong>
                      <span className="card__hint">
                        {t('fam.bornOn', {
                          date: fmtDate(c.birthDate, 'd MMMM yyyy', locale),
                          growth: growth.filter((g) => g.childId === c.id).length,
                          imm: immunizations.filter((i) => i.childId === c.id && i.given).length,
                        })}
                      </span>
                    </span>
                    <VisibilityBadge visibility={c.visibility} />
                  </li>
                ))}
              </ul>
            )}
          </Card>

          {children.length > 0 && (
            <>
              <Card
                title={t('fam.growth')}
                icon="health"
                action={
                  <button className="btn btn--sm" onClick={() => setSheet('growth')}>
                    <Icon name="plus" size={16} /> {t('fam.measure')}
                  </button>
                }
              >
                {growth.length === 0 ? (
                  <EmptyState icon="health" title={t('fam.noGrowth')} />
                ) : (
                  <div className="table-scroll">
                  <table>
                    <caption className="visually-hidden">{t('fam.growthCaption')}</caption>
                    <thead>
                      <tr>
                        <th scope="col" style={th}>{t('common.date')}</th>
                        <th scope="col" style={th}>{t('cyc.painHigh')}</th>
                        <th scope="col" style={th}>{t('fam.height')}</th>
                        <th scope="col" style={th}>{t('fam.head')}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {growth.map((g) => (
                        <tr key={g.id}>
                          <th scope="row" style={td}>{fmtDate(g.date, 'd MMM yy', locale)}</th>
                          <td style={td}>{g.weightKg ? `${g.weightKg} kg` : '—'}</td>
                          <td style={td}>{g.heightCm ? `${g.heightCm} cm` : '—'}</td>
                          <td style={td}>{g.headCm ? `${g.headCm} cm` : '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  </div>
                )}
                <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>{t('fam.growthDisclaimer')}
                </p>
              </Card>

              <Card
                title={t('fam.immunization')}
                icon="consent"
                action={
                  <button className="btn btn--sm" onClick={() => setSheet('immunization')}>
                    <Icon name="plus" size={16} /> {t('cyc.record')}
                  </button>
                }
                hint={t('fam.immunizationHint')}
              >
                {immunizations.length === 0 ? (
                  <EmptyState icon="consent" title={t('today.noUnsaid')} />
                ) : (
                  <ul className="list">
                    {immunizations.map((i) => (
                      <li key={i.id} className="list__item">
                        <button
                          className="btn btn--ghost btn--sm btn--icon"
                          aria-label={t('fam.markGiven', { name: i.vaccine })}
                          onClick={() => patch('family', i.id, { given: !i.given })}
                        >
                          <Icon name={i.given ? 'check' : 'plus'} size={16} />
                        </button>
                        <span className="grow stack stack--tight">
                          <strong style={{ fontSize: 14 }}>{i.vaccine}</strong>
                          <span className="card__hint">
                            {i.given ? t('fam.given') : t('fam.planned')} · {whenLabel(i.date, t, locale)}
                          </span>
                        </span>
                      </li>
                    ))}
                  </ul>
                )}
              </Card>
            </>
          )}
        </>
      )}

      {on.includes('coparenting') && (
        <Card
          title={t('fam.shifts')}
          icon="family"
          action={
            <button className="btn btn--sm" onClick={() => setSheet('shift')}>
              <Icon name="plus" size={16} /> {t('fam.shift')}
            </button>
          }
          hint={t('fam.shiftsHint')}
        >
          {shifts.length === 0 ? (
            <EmptyState icon="family" title={t('fam.noShifts')} />
          ) : (
            <ul className="list">
              {shifts.map((s) => (
                <li key={s.id} className="list__item">
                  <Icon name="family" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>
                      {profiles.find((p) => p.id === s.caregiverProfileId)?.displayName ?? '—'} · {s.from}–{s.to}
                    </strong>
                    <span className="card__hint">{whenLabel(s.date, t, locale)}</span>
                    {s.handoverNote && <span className="card__hint">“{s.handoverNote}”</span>}
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('family', s.id, me)}>
                    <Icon name="close" size={16} label={t('fam.deleteShift')} />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Card>
      )}

      <Card title={t('fam.consultCard')} icon="referral">
        <Link to="/bantuan" className="btn btn--ghost btn--block">
          <Icon name="referral" size={18} />{t('fam.prepQuestions')}
        </Link>
      </Card>

      <p className="disclaimer">{t('fam.disclaimer')}
      </p>

      <FamilySheet kind={sheet} onClose={() => setSheet(null)} me={me} profiles={profiles} children={children} />
    </div>
  )
}

const th: React.CSSProperties = { textAlign: 'left', padding: '5px 4px', borderBottom: '1px solid var(--border)', fontWeight: 800, fontSize: 12 }
const td: React.CSSProperties = { textAlign: 'left', padding: '5px 4px', borderBottom: '1px solid var(--border)', fontWeight: 400 }

function FamilySheet({
  kind,
  onClose,
  me,
  profiles,
  children,
}: {
  kind: SheetKind
  onClose: () => void
  me: string
  profiles: { id: string; displayName: string }[]
  children: Extract<FamilyRecord, { kind: 'child' }>[]
}) {
  const t = useT()
  const [text, setText] = useState('')
  const [date, setDate] = useState(format(new Date(), 'yyyy-MM-dd'))
  const [time, setTime] = useState('')
  const [place, setPlace] = useState('')
  const [questions, setQuestions] = useState('')
  const [childId, setChildId] = useState(children[0]?.id ?? '')
  const [w, setW] = useState('')
  const [h, setH] = useState('')
  const [head, setHead] = useState('')
  const [from, setFrom] = useState('06:00')
  const [to, setTo] = useState('12:00')
  const [caregiver, setCaregiver] = useState(me)

  function reset() {
    setText('')
    setQuestions('')
    setW('')
    setH('')
    setHead('')
    setPlace('')
    setTime('')
  }

  async function save() {
    // Health class keeps body data private by default; child logistics are the
    // household's shared business, so they go to C2.
    const health = newEnvelope(me, 'C4_health')
    const shared = newEnvelope(me, 'C2_shared_ops')

    if (kind === 'pregnancy') {
      await db.family.add({ ...health, kind: 'pregnancy', lmpDate: date, status: 'jalan' } as never)
    } else if (kind === 'appointment') {
      if (!text.trim()) return
      await db.family.add({
        ...health,
        kind: 'appointment',
        title: text.trim(),
        date,
        ...(time ? { time } : {}),
        ...(place.trim() ? { place: place.trim() } : {}),
        questions: questions.split('\n').map((q) => q.trim()).filter(Boolean),
      } as never)
    } else if (kind === 'birth_plan') {
      if (!text.trim()) return
      await db.family.add({ ...health, kind: 'birth_plan', preference: text.trim() } as never)
    } else if (kind === 'support_request') {
      if (!text.trim()) return
      await db.family.add({ ...shared, kind: 'support_request', action: text.trim(), status: 'diminta' } as never)
    } else if (kind === 'child') {
      if (!text.trim()) return
      await db.family.add({ ...shared, kind: 'child', name: text.trim(), birthDate: date } as never)
    } else if (kind === 'growth') {
      if (!childId) return
      await db.family.add({
        ...shared,
        kind: 'growth',
        childId,
        date,
        ...(w ? { weightKg: Number(w) } : {}),
        ...(h ? { heightCm: Number(h) } : {}),
        ...(head ? { headCm: Number(head) } : {}),
      } as never)
    } else if (kind === 'immunization') {
      if (!childId || !text.trim()) return
      await db.family.add({
        ...shared,
        kind: 'immunization',
        childId,
        vaccine: text.trim(),
        date,
        given: false,
      } as never)
    } else if (kind === 'shift') {
      await db.family.add({
        ...shared,
        kind: 'shift',
        ...(childId ? { childId } : {}),
        date,
        from,
        to,
        caregiverProfileId: caregiver,
        ...(text.trim() ? { handoverNote: text.trim() } : {}),
      } as never)
    }
    reset()
    onClose()
  }

  const dateLabel: Record<NonNullable<SheetKind>, MessageKey> = {
    pregnancy: 'fam.lmp',
    appointment: 'fam.appointmentDate',
    birth_plan: 'common.date',
    support_request: 'common.date',
    child: 'fam.birthDate',
    growth: 'fam.measureDate',
    immunization: 'common.date',
    shift: 'common.date',
  }

  return (
    <Sheet open={kind !== null} onClose={onClose} title={kind ? t(`fam.sheet.${kind}` as const) : ''}>
      <div className="stack">
        {kind && ['appointment', 'birth_plan', 'support_request', 'child', 'immunization', 'shift'].includes(kind) && (
          <Field
            label={
              kind === 'child'
                ? t('fam.childName')
                : kind === 'immunization'
                  ? t('fam.vaccine')
                  : kind === 'shift'
                    ? t('fam.handover')
                    : kind === 'support_request'
                      ? t('fam.supportNeeded')
                      : kind === 'birth_plan'
                        ? t('fam.yourPreference')
                        : t('fam.whatCheckup')
            }
            hint={kind === 'shift' ? 'Boleh dikosongin.' : undefined}
          >
            {(p) =>
              kind === 'birth_plan' || kind === 'support_request' || kind === 'shift' ? (
                <textarea {...p} value={text} onChange={(e) => setText(e.target.value)} />
              ) : (
                <input {...p} type="text" value={text} onChange={(e) => setText(e.target.value)} />
              )
            }
          </Field>
        )}

        {kind && ['growth', 'immunization', 'shift'].includes(kind) && children.length > 0 && (
          <Field label={t('fam.whichChild')}>
            {(p) => (
              <select {...p} value={childId} onChange={(e) => setChildId(e.target.value)}>
                {kind === 'shift' && <option value="">{t('fam.allChildren')}</option>}
                {children.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            )}
          </Field>
        )}

        {kind && (
          <Field label={t(dateLabel[kind])}>
            {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
          </Field>
        )}

        {kind === 'appointment' && (
          <>
            <Field label={t('common.time')} hint={t('common.optional')}>
              {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
            </Field>
            <Field label={t('fam.where')} hint={t('common.optional')}>
              {(p) => <input {...p} type="text" value={place} onChange={(e) => setPlace(e.target.value)} />}
            </Field>
            <Field label={t('fam.questions')} hint={t('fam.questionsHint')}>
              {(p) => <textarea {...p} value={questions} onChange={(e) => setQuestions(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'growth' && (
          <>
            <Field label={t('fam.weightKg')}>
              {(p) => <input {...p} type="number" step="0.1" min="0" value={w} onChange={(e) => setW(e.target.value)} />}
            </Field>
            <Field label={t('fam.heightCm')}>
              {(p) => <input {...p} type="number" step="0.1" min="0" value={h} onChange={(e) => setH(e.target.value)} />}
            </Field>
            <Field label={t('fam.headCm')} hint={t('common.optional')}>
              {(p) => <input {...p} type="number" step="0.1" min="0" value={head} onChange={(e) => setHead(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'shift' && (
          <>
            <div className="row" style={{ gap: 'var(--space-3)' }}>
              <div className="grow">
                <Field label={t('fam.fromTime')}>
                  {(p) => <input {...p} type="time" value={from} onChange={(e) => setFrom(e.target.value)} />}
                </Field>
              </div>
              <div className="grow">
                <Field label={t('fam.toTime')}>
                  {(p) => <input {...p} type="time" value={to} onChange={(e) => setTo(e.target.value)} />}
                </Field>
              </div>
            </div>
            <Field label={t('fam.caregiver')}>
              {(p) => (
                <select {...p} value={caregiver} onChange={(e) => setCaregiver(e.target.value)}>
                  {profiles.map((x) => (
                    <option key={x.id} value={x.id}>
                      {x.displayName}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}

        {kind === 'pregnancy' && (
          <p className="disclaimer">{t('fam.pregnancyPrivate')}
          </p>
        )}

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
